/// What the user chose when unsaved changes would be left behind.
enum UnsavedChoice { save, discard, cancel }

/// The three-way prompt (S5.8; ADR-019 §3, addendum §3.3): "[plan] has
/// changes that are not saved." with Cancel · Discard · Save. Dismissing
/// it (back, a tap outside) is Cancel, so nothing is lost by accident.
/// What Save and Discard then do belongs to the caller (P6.1); this is the
/// prompt only. Discard is styled as destructive.
Future<UnsavedChoice> askUnsavedChanges(
  BuildContext context, {
  required String plan,
}) async {
  final choice = await showDialog<UnsavedChoice>(
    context: context,
    builder: (context) => AlertDialog(
      title: const Text('Unsaved changes'),
      content: Text('"$plan" has changes that are not saved.'),
      actions: [
        TextButton(
          key: const Key('unsaved.cancel'),
          onPressed: () => Navigator.pop(context, UnsavedChoice.cancel),
          child: const Text('Cancel'),
        ),
        TextButton(
          key: const Key('unsaved.discard'),
          style: AppButtonStyles.destructiveText(Theme.of(context).colorScheme),
          onPressed: () => Navigator.pop(context, UnsavedChoice.discard),
          child: const Text('Discard'),
        ),
        TextButton(
          key: const Key('unsaved.save'),
          onPressed: () => Navigator.pop(context, UnsavedChoice.save),
          child: const Text('Save'),
        ),
      ],
    ),
  );
  return choice ?? UnsavedChoice.cancel;
}

/// The one confirmation for a destructive action on something stored
/// (S5.8; RD-09 = M): deleting a rig, a target, a site or a Logbook entry,
/// Abandon, Restore. [title] names the item ("Delete rig "Refractor
/// 400"?"), [message] says the consequence ("Plans that use it keep their
/// saved values."), [action] is the verb on the destructive button
/// ("Delete"). True only when the user taps [action]: Cancel, back and a
/// tap outside all keep the item. Edits inside a plan use the undo message
/// instead (`showUndo`).
Future<bool> confirmDestructive(
  BuildContext context, {
  required String title,
  required String message,
  String action = 'Delete',
}) async {
  final confirmed = await showDialog<bool>(
    context: context,
    builder: (context) => AlertDialog(
      title: Text(title),
      content: Text(message),
      actions: [
        TextButton(
          key: const Key('confirm.cancel'),
          onPressed: () => Navigator.pop(context, false),
          child: const Text('Cancel'),
        ),
        TextButton(
          key: const Key('confirm.action'),
          style: AppButtonStyles.destructiveText(Theme.of(context).colorScheme),
          onPressed: () => Navigator.pop(context, true),
          child: Text(action),
        ),
      ],
    ),
  );
  return confirmed ?? false;
}

import 'package:flutter/material.dart';

import '../../core/theme/app_radius.dart';
import '../../core/theme/app_spacing.dart';
import 'app_messages.dart';

// Deleting (S5.8; RD-09 = M + S1, DECISIONS E.1):
// - an edit inside a plan (a capture block) happens at once, with an Undo
//   message: [showUndo];
// - a stored record (a rig, a target, a site, a Logbook entry) is deleted
//   only after the shared confirmation (`confirmDestructive`);
// - every deletable item has a visible Delete ([DeleteButton]); a swipe
//   ([SwipeToDelete]) is a shortcut to the same handler.

/// Shows "[message] · Undo" after an edit was applied, and reports exactly
/// one outcome: [onUndo] when the user taps Undo, otherwise [onCommit] once
/// the message closes (it timed out, was swiped away or replaced by
/// another). The edit is applied before the message shows; [onUndo]
/// restores it. Returns whether it was undone.
Future<bool> showUndo(
  BuildContext context, {
  required String message,
  required VoidCallback onUndo,
  VoidCallback? onCommit,
  Duration duration = const Duration(seconds: 6),
}) async {
  final messenger = ScaffoldMessenger.of(context);
  messenger.hideCurrentSnackBar();
  final reason = await messenger
      .showMessage(
        SnackBar(
          content: Text(message),
          duration: duration,
          // A message with an action stays until dismissed unless told
          // otherwise (Flutter's `persist`); Undo must time out and commit.
          persist: false,
          action: SnackBarAction(label: 'Undo', onPressed: () {}),
        ),
      )
      .closed;
  final undone = reason == SnackBarClosedReason.action;
  if (undone) {
    onUndo();
  } else {
    onCommit?.call();
  }
  return undone;
}

/// The visible Delete (S1; UX-38): an icon button with its label as the
/// tooltip, e.g. "Delete rig". Where it sits (a row's menu, the item's
/// editor, the row itself) is decided where it is adopted.
class DeleteButton extends StatelessWidget {
  const DeleteButton({
    super.key,
    required this.tooltip,
    required this.onPressed,
  });

  final String tooltip;
  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) => IconButton(
    tooltip: tooltip,
    onPressed: onPressed,
    icon: const Icon(Icons.delete_outline),
  );
}

/// A swipe from the end is a shortcut to [onDelete], the same handler as
/// the row's visible Delete (S1). The row never stays slid away behind a
/// dialog (08 §20): it springs back at once, and [onDelete] then confirms
/// (a stored record) or deletes with Undo (an edit inside a plan); the list
/// drops the row when the item is really gone.
class SwipeToDelete extends StatelessWidget {
  const SwipeToDelete({
    super.key,
    required this.itemKey,
    required this.onDelete,
    required this.child,
  });

  /// Unique within the list, e.g. `ValueKey('rig_3')`.
  final Key itemKey;
  final VoidCallback onDelete;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Dismissible(
      key: itemKey,
      direction: DismissDirection.endToStart,
      background: Container(
        decoration: BoxDecoration(
          color: scheme.error,
          borderRadius: BorderRadius.circular(AppRadius.large),
        ),
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: AppSpacing.md),
        child: Icon(Icons.delete_outline, color: scheme.onError),
      ),
      confirmDismiss: (_) async {
        onDelete();
        return false; // spring back; the list removes the row when deleted
      },
      child: child,
    );
  }
}

import 'dart:math' as math;

import 'package:flutter/material.dart';

import '../../core/theme/app_colors.dart';
import '../../core/theme/app_motion.dart';

/// The Culmina mark shown while startup really loads (S13.3, ID-6 = S2): it
/// continues the Android 12+ splash in the same colours. The star breathes
/// softly only while the view is on screen, which is only while loading — no
/// progress is implied — and stays still when the platform asks for less
/// motion. The geometry is the launcher icon's
/// (`drawable/ic_launcher_foreground.xml`, 108-unit canvas; trap 20).
class StartupMark extends StatefulWidget {
  const StartupMark({super.key, this.size = 112});

  /// The diameter of the navy disc behind the mark, in logical pixels.
  final double size;

  @override
  State<StartupMark> createState() => _StartupMarkState();
}

class _StartupMarkState extends State<StartupMark>
    with SingleTickerProviderStateMixin {
  /// One breath of the star: bright → dim → bright.
  static const Duration breath = Duration(milliseconds: 1600);

  late final AnimationController _breath = AnimationController(
    vsync: this,
    duration: breath,
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (AppMotion.duration(context, breath) == Duration.zero) {
      _breath
        ..stop()
        ..value = 0;
    } else if (!_breath.isAnimating) {
      _breath.repeat();
    }
  }

  @override
  void dispose() {
    _breath.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label: 'Loading',
      liveRegion: true,
      child: ExcludeSemantics(
        child: SizedBox.square(
          dimension: widget.size,
          child: AnimatedBuilder(
            animation: _breath,
            builder: (context, _) => CustomPaint(
              painter: _MarkPainter(
                // 1 at rest and at both ends of a breath, 0.6 at its middle.
                starOpacity:
                    1 - 0.4 * (1 - math.cos(2 * math.pi * _breath.value)) / 2,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _MarkPainter extends CustomPainter {
  _MarkPainter({required this.starOpacity});

  final double starOpacity;

  static const _navy = AppColors.markNavy;
  static const _orbit = AppColors.markOrbit;
  static const _inner = AppColors.markInnerOrbit;
  static const _star = AppColors.markStar;

  /// Degrees, counter-clockwise from east with y up, as the vector's arcs.
  static Rect _circle(double r) =>
      Rect.fromCircle(center: const Offset(54, 54), radius: r);

  static double _rad(double degrees) => degrees * math.pi / 180;

  @override
  void paint(Canvas canvas, Size size) {
    final r = size.shortestSide / 2;
    canvas.drawCircle(size.center(Offset.zero), r, Paint()..color = _navy);
    // The disc shows the launcher's 72-unit visible area (18..90).
    final scale = size.shortestSide / 72;
    canvas
      ..save()
      ..scale(scale)
      ..translate(-18, -18);
    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round;
    canvas.drawArc(
      _circle(13.2),
      _rad(-94.08),
      _rad(-(345.92 - 94.08)),
      false,
      stroke
        ..color = _inner
        ..strokeWidth = 2.4,
    );
    canvas.drawArc(
      _circle(22),
      _rad(-72.07),
      _rad(-(367.94 - 72.07)),
      false,
      stroke
        ..color = _orbit
        ..strokeWidth = 6,
    );
    final star = Path()
      ..moveTo(70.85, 30.26)
      ..quadraticBezierTo(72.39, 38.32, 80.45, 39.86)
      ..quadraticBezierTo(72.39, 41.39, 70.85, 49.46)
      ..quadraticBezierTo(69.32, 41.39, 61.25, 39.86)
      ..quadraticBezierTo(69.32, 38.32, 70.85, 30.26)
      ..close();
    canvas
      ..drawPath(star, Paint()..color = _star.withValues(alpha: starOpacity))
      ..restore();
  }

  @override
  bool shouldRepaint(_MarkPainter old) => old.starOpacity != starOpacity;
}

